#include <bits/stdc++.h>
using namespace std;
int main() {
    int h, w;
    cin >> h >> w;
    int n = h * w;
    vector<int> a(n), mt(n, -1), seen(n);
    for (int &x : a)
        cin >> x;
    function<bool(int)> dfs = [&](int u) {
        int r = u / w, c = u % w;
        for (auto [dr, dc] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int y = r + dr, x = c + dc;
            if (y < 0 || y >= h || x < 0 || x >= w)
                continue;
            int v = y * w + x;
            if (a[u] != a[v] || seen[v])
                continue;
            seen[v] = 1;
            if (mt[v] < 0 || dfs(mt[v])) {
                mt[v] = u;
                return true;
            }
        }
        return false;
    };
    int ans = 0;
    for (int u = 0; u < n; u++)
        if ((u / w + u % w) % 2 == 0) {
            fill(seen.begin(), seen.end(), 0);
            ans += dfs(u);
        }
    cout << ans << '\n';
}

