def dfs(u):

    r, c = divmod(u, w)

    for y, x in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
        if 0 <= y < h and 0 <= x < w:
            v = y * w + x

            if a[u] == a[v] and v not in seen:
                seen.add(v)

                if mt[v] < 0 or dfs(mt[v]):
                    mt[v] = u
                    return True

    return False


ans = 0

for u in range(h * w):
    if (u // w + u % w) % 2 == 0:
        seen = set()
        ans += dfs(u)

