import sys, math

v = list(map(int, sys.stdin.read().split()))
x = v[0]
d = sorted(set(v[1:]), reverse=True)
h = math.gcd(*d)
x //= h
d = [a // h for a in d]
best = 2 * d[0] + x // d[0] + 1


def eg(a, b):
    if b == 0:
        return (a, 1, 0)
    g, u, v = eg(b, a % b)
    return (g, v, u - a // b * v)


def two(a, b, r):
    g, u, v = eg(a, b)
    if r % g:
        return 10**100
    u *= r // g
    v *= r // g
    A = a // g
    B = b // g
    return min(
        (
            abs(u + t * B) + abs(v - t * A)
            for root in (-u // B, v // A, 0)
            for t in range(root - 1, root + 2)
        )
    )


for a in d:
    if x % a == 0:
        best = min(best, x // a)
for i, a in enumerate(d):
    for b in d[:i]:
        best = min(best, two(a, b, x))
g = [0] * len(d)
for i in range(len(d) - 1, -1, -1):
    g[i] = math.gcd(d[i], g[i + 1] if i + 1 < len(d) else 0)


def prepare_ap(a, b, h):
    assert 0 < a < b and h > 0 and (b - a) % h == 0
    g = math.gcd(a, h)
    a, b, h = a // g, b // g, h // g
    return a, b, h, g, (pow(a, -1, h) if h > 1 else 0)


def ceil_div(a, b):
    return -((-a) // b)


def feasible_ap(ctx, x, K):
    if K < 0:
        return False
    a, b, h, g, inv = ctx
    x = abs(x)
    if x % g:
        return False
    x //= g
    lo = max(-K, ceil_div(2 * x - (b - a) * K, a + b))
    hi = min(K, (2 * x + (b - a) * K) // (a + b))
    if lo > hi:
        return False
    residue = (x % h) * inv % h
    if h & 1:
        if (residue - K) & 1:
            residue += h
        step = 2 * h
    else:
        if (residue - K) & 1:
            return False
        step = h
    return residue + ceil_div(lo - residue, step) * step <= hi


def minimum_ap(ctx, x, upper):
    answer = upper + 1
    for parity in (0, 1):
        if upper < parity:
            continue
        last = upper - ((upper - parity) & 1)
        if not feasible_ap(ctx, x, last):
            continue
        lo, hi = 0, (last - parity) // 2
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible_ap(ctx, x, parity + 2 * mid):
                hi = mid
            else:
                lo = mid + 1
        answer = min(answer, parity + 2 * lo)
    return answer


ap_contexts = [None] * len(d)
full_ap = [False] * len(d)
ap_step = 0
for index in range(len(d) - 1, -1, -1):
    ap_step = math.gcd(ap_step, d[index] - d[-1])
    if ap_step:
        ap_contexts[index] = prepare_ap(d[-1], d[index], ap_step)
        full_ap[index] = (d[index] - d[-1]) // ap_step + 1 == len(d) - index


def dfs(i, r, used):
    global best
    r = abs(r)
    if not r:
        best = min(best, used)
        return
    if used >= best or r % g[i] or used + (r + d[i] - 1) // d[i] >= best:
        return
    if len(d) - i == 1:
        if r % d[i] == 0:
            best = min(best, used + r // d[i])
        return
    if len(d) - i == 2:
        best = min(best, used + two(d[i], d[i + 1], r))
        return
    lower = minimum_ap(ap_contexts[i], r, best - used)
    if lower >= best - used:
        return
    if full_ap[i]:
        best = used + lower
        return
    B = best - used - 1
    lo = max(-B, -(-(r - B * d[i + 1]) // d[i]))
    hi = min(B, (r + B * d[i + 1]) // d[i])
    h = math.gcd(d[i], g[i + 1])
    if r % h:
        return
    step = g[i + 1] // h
    res = 0 if step == 1 else r // h * pow(d[i] // h, -1, step) % step
    first = res + -(-(lo - res) // step) * step
    last = res + (hi - res) // step * step
    if first > last:
        return
    mid = min(last, max(first, res + (r // d[i] - res) // step * step))
    dist = 0
    while mid + dist <= last or mid - dist >= first:
        for c in (mid,) if dist == 0 else (mid + dist, mid - dist):
            if not first <= c <= last:
                continue
            cost = abs(c)
            rem = r - c * d[i]
            if used + cost + (abs(rem) + d[i + 1] - 1) // d[i + 1] < best:
                dfs(i + 1, rem, used + cost)
        dist += step


dfs(0, x, 0)
print(best)

