    for (int j = 1; j < n; j++)
        pos[r[best][j]] = j;
    vector<pair<int, int>> v;
    for (int i = 0; i < m; i++) {
        vector<int> tail;
        for (int j = 1; j < n; j++) {
            int x = pos[r[i][j]];
            auto it = lower_bound(tail.begin(), tail.end(), x);
            if (it == tail.end())
                tail.push_back(x);
            else
                *it = x;
        }
        v.push_back({tail.size() + 2, i});
    }
    sort(v.begin(), v.end());
    vector<int> dp(m, 1);
    int ans = 1;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < i; j++)
            if (v[j].first < v[i].first && d[v[j].second] > d[v[i].second])
