#include <bits/stdc++.h>
using namespace std;
const double NEG = -1e100;
using Mat = vector<vector<double>>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    const double pi = acos(-1.0);
    cout << fixed << setprecision(4);
    while (cin >> n >> k) {
        vector<double> a(2 * n);
        for (int i = 0; i < n; i++)
            cin >> a[i];
        sort(a.begin(), a.begin() + n);
        for (int i = 0; i < n; i++)
            a[i + n] = a[i] + 2 * pi;
        bool possible = true;
        for (int i = 0; i < n; i++)
            if (a[i + 1] - a[i] > pi)
                possible = false;
        if (!possible) {
            cout << 0.0 << '\n';
            continue;
        }
        auto area = [&](vector<int> v) {
            double s = 0;
            for (int j = 0; j < k; j++) {
                double gap =
                    j + 1 < k ? a[v[j + 1]] - a[v[j]] : a[v[0]] + 2 * pi - a[v[j]];
                if (gap > pi)
                    return NEG;
                s += sin(gap) / 2;
            }
            return s;
        };
        if (k == n) {
            double s = 0;
            for (int i = 0; i < n; i++)
                s += sin(a[i + 1] - a[i]) / 2;
            cout << max(0.0, s) << '\n';
            continue;
        }
        double best = 0;
        for (int start = 0; start < min(n, 32); start++) {
            vector<int> v;
            for (int j = 0; j < k; j++)
                v.push_back(start + j * n / k);
            best = max(best, area(v));
        }
        double upper = k * sin(2 * pi / k) / 2;
        auto rounded = [&](double x) { return (long long)floor(x * 10000 + 0.5); };
        if (rounded(best - 1e-11) == rounded(upper + 1e-11)) {
            cout << best << '\n';
            continue;
        }
        vector<int> nxt(2 * n);
        for (int i = 0, j = 0; i < 2 * n; i++) {
            j = max(j, i);
            while (j + 1 < 2 * n && a[j + 1] - a[i] <= pi)
                j++;
            nxt[i] = j;
        }
        int lg = 1;
        while ((1 << lg) <= k)
            lg++;
        vector<vector<int>> up(lg, nxt);
        for (int l = 1; l < lg; l++)
            for (int i = 0; i < 2 * n; i++)
                up[l][i] = up[l - 1][up[l - 1][i]];
        auto reach = [&](int i, int c) {
            for (int l = 0; c; c >>= 1, l++)
                if (c & 1)
                    i = up[l][i];
            return i;
        };
        auto mul = [&](const Mat &A, int ca, const Mat &B, int cb) {
            Mat C(n, vector<double>(n, NEG));
            int count = ca + cb;
            for (int from = 0; from < n; from++) {
                int hi = min(n, reach(from, count) - from);
                if (hi < count)
                    continue;
                vector<array<int, 4>> st = {{count, hi, ca, n - cb}};
                while (!st.empty()) {
                    auto [l, r, bl, br] = st.back();
                    st.pop_back();
                    if (l > r)
                        continue;
                    int mid = (l + r) / 2, end = (from + mid) % n, bm = bl;
                    double val = NEG;
                    for (int t = bl; t <= br && t <= mid - cb; t++) {
                        double x = A[from][(from + t) % n], y = B[(from + t) % n][end];
                        if (x > NEG / 2 && y > NEG / 2 && x + y > val)
                            val = x + y, bm = t;
                    }
                    C[from][end] = val;
                    st.push_back({l, mid - 1, bl, bm});
                    st.push_back({mid + 1, r, bm, br});
                }
            }
            return C;
        };
        Mat base(n, vector<double>(n, NEG)), ans;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j <= nxt[i] && j < i + n; j++)
                base[i][j % n] = sin(a[j] - a[i]) / 2;
        int power = 1, count = 0, e = k;
        while (e) {
            if (e & 1) {
                if (!count)
                    ans = base, count = power;
                else
                    ans = mul(ans, count, base, power), count += power;
            }
            e >>= 1;
            if (e) {
                base = mul(base, power, base, power);
                power *= 2;
            }
        }
        for (int i = 0; i < n; i++)
            best = max(best, ans[i][i]);
        cout << max(0.0, best) << '\n';
    }
}

