    vector<int> sum(z);
    for (int m = 1; m < z; m++) {
        int b = __builtin_ctz((unsigned)m);
        sum[m] = sum[m ^ (1 << b)] + a[b];
    }
    vector<long long> dp(z, -1);
    function<long long(int)> f = [&](int m) -> long long {
        if (!m)
            return 1;
        if (dp[m] >= 0)
            return dp[m];
        long long ans = 0;
        int bit = m & -m;
        for (int sub = m; sub; sub = (sub - 1) & m)
            if ((sub & bit) && __builtin_popcount((unsigned)sub) == s)
                ans = max(ans, 1LL * sum[sub] * f(m ^ sub));
        return dp[m] = ans;
    };
    cout << f(z - 1) << '\n';
}

