#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
cpp_int gcdBig(cpp_int a, cpp_int b) {
    if (a < 0)
        a = -a;
    if (b < 0)
        b = -b;
    while (b != 0) {
        cpp_int r = a % b;
        a = b;
        b = r;
    }
    return a;
}

struct Rat {
    cpp_int p, q;
    Rat(cpp_int a = 0, cpp_int b = 1) : p(a), q(b) {
        if (q < 0)
            p = -p, q = -q;
        cpp_int g = gcdBig(p, q);
        p /= g;
        q /= g;
    }
};

Rat operator+(Rat a, Rat b) {
    return Rat(a.p * b.q + b.p * a.q, a.q * b.q);
}
Rat operator-(Rat a, Rat b) {
    return Rat(a.p * b.q - b.p * a.q, a.q * b.q);
}
Rat operator*(Rat a, Rat b) {
    return Rat(a.p * b.p, a.q * b.q);
}
Rat operator/(Rat a, Rat b) {
    return Rat(a.p * b.q, a.q * b.p);
}

int common(string a, string b) {
    vector<int> d(b.size() + 1);
    int ans = 0;
    for (char x : a) {
        for (int j = b.size(); j >= 1; j--) {
            d[j] = x == b[j - 1] ? d[j - 1] + 1 : 0;
            ans = max(ans, d[j]);
        }
    }
    return ans;
}

