            bounds.erase(unique(bounds.begin(), bounds.end()), bounds.end());
            sort(hi.begin(), hi.end(), [](auto a, auto b) { return a.l < b.l; });
            int k = bounds.size() - 1, j = 0;
            vector<int> E(k), S(k);
            priority_queue<int, vector<int>, greater<int>> ends;
            priority_queue<pair<int, int>> starts;
            bool cover = true;
            for (int t = 0; t < k; t++) {
                int x = bounds[t];
                while (j < (int)hi.size() && hi[j].l <= x) {
                    ends.push(hi[j].r);
                    starts.push({hi[j].l, hi[j].r});
                    j++;
                }
                while (!ends.empty() && ends.top() < x)
                    ends.pop();
                while (!starts.empty() && starts.top().second < x)
                    starts.pop();
                if (ends.empty()) {
                    cover = false;
                    break;
                }
                E[t] = ends.top();
                S[t] = starts.top().first;
            }
            if (!cover)
                continue;
            ans = min(ans, low.id);
            vector<int> pref(k + 1, low.l - 1), suf(k + 1, low.r + 1);
            for (int t = 0; t < k; t++)
                pref[t + 1] = max(pref[t], E[t]);
            for (int t = k - 1; t >= 0; t--)
                suf[t] = min(suf[t + 1], S[t]);
            for (auto z : hi) {
                int l = lower_bound(bounds.begin(), bounds.end(), z.l) - bounds.begin(),
                    r = lower_bound(bounds.begin(), bounds.end(), z.r + 1) -
                        bounds.begin();
                if (max(z.l, pref[l] + 1) <= min(z.r, suf[r] - 1))
                    ans = min(ans, z.id);
            }
        }
        cout << (ans == q + 1 ? 0 : ans) << '\n';
    }
}

