it = iter(map(int, sys.stdin.buffer.read().split()))

for n in it:
    q = next(it)

    if n == q == 0:
        break

    v = [(next(it), next(it), next(it), i + 1) for i in range(q)]
    ans = min([i for l, r, a, i in v if not 1 <= a <= 1000000] + [q + 1])

    for L, R, a, idx in v:
        if not 1 <= a <= 1000000:
            continue

        hi = sorted(
            (max(L, l), min(R, r), i)
            for l, r, b, i in v
            if a < b <= 1000000 and max(L, l) <= min(R, r)
        )
        bounds = sorted({L, R + 1} | {x for l, r, i in hi for x in (l, r + 1)})
        k = len(bounds) - 1
        ends = []
        starts = []
        E = []
        S = []
        j = 0

        for x in bounds[:-1]:
            while j < len(hi) and hi[j][0] <= x:
                l, r, i = hi[j]
                heapq.heappush(ends, r)
                heapq.heappush(starts, (-l, r))
                j += 1

            while ends and ends[0] < x:
                heapq.heappop(ends)

            while starts and starts[0][1] < x:
                heapq.heappop(starts)

            if not ends:
                break

            E.append(ends[0])
            S.append(-starts[0][0])

        if len(E) != k:
            continue

        ans = min(ans, idx)
        pref = [L - 1]
        suf = [R + 1] * (k + 1)

        for e in E:
            pref.append(max(pref[-1], e))

        for j in range(k - 1, -1, -1):
            suf[j] = min(suf[j + 1], S[j])

        for l, r, i in hi:
            a = bisect.bisect_left(bounds, l)
            b = bisect.bisect_left(bounds, r + 1)

            if max(l, pref[a] + 1) <= min(r, suf[b] - 1):
                ans = min(ans, i)

    print(0 if ans == q + 1 else ans)

