        auto skip = [&]() {
            while (i < s.size() && isspace((unsigned char)s[i]))
                i++;
        };
        auto num = [&]() {
            skip();
            cpp_int n = 0;
            size_t st = i;
            while (i < s.size() && isdigit((unsigned char)s[i]))
                n = n * 10 + s[i++] - '0';
            if (i == st || n == 0)
                ok = false;
            return n;
        };
        auto frac = [&]() {
            cpp_int a = num();
            skip();
            if (i >= s.size() || s[i++] != '/')
                ok = false;
            cpp_int b = num();
            if (b == 0)
                b = 1;
            return Rat(a, b);
        };
        Rat sum, term = frac();
        int sign = 1;
        while (ok) {
            skip();
            if (i == s.size())
                break;
            char op = s[i++];
            if (string("+-*/").find(op) == string::npos) {
