                    while (z) {
                        s += z % 10;
                        z /= 10;
                    }
                    ans = max(ans, s);
                }
                return;
            }
            if (m - i > n - j)
                f(i + 1, j, x * 10);
            if (j < n)
                f(i + 1, j + 1, x * 10 + b[j] - '0');
        };
        f(0, 0, 0);
        cout << ans << '\n';
    }
}

