#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
cpp_int ten(int k) {
    cpp_int x = 1;
    while (k--)
        x *= 10;
    return x;
}

struct Dec {
    cpp_int n;
    int s;
    Dec(cpp_int a = 0, int b = 0) : n(a), s(b) {
    }
    Dec(string x) {
        s = 0;
        n = 0;
        bool neg = false, point = false;
        for (char c : x) {
            if (c == '-')
                neg = true;
            else if (c == '.')
                point = true;
            else if (isdigit(c)) {
                n = n * 10 + c - '0';
                s += point;
            }
        }
        if (neg)
            n = -n;
    }
    string str() const {
        cpp_int q = n;
        bool neg = q < 0;
        if (neg)
            q = -q;
        string x = q.convert_to<string>();
        if (s) {
            if ((int)x.size() <= s)
                x = string(s + 1 - x.size(), '0') + x;
            x.insert(x.size() - s, 1, '.');
            while (x.back() == '0')
                x.pop_back();
            if (x.back() == '.')
                x.pop_back();
        }
        if (neg && q != 0)
            x = "-" + x;
        return x;
    }
};

Dec operator+(Dec a, Dec b) {
    int s = max(a.s, b.s);
    return Dec(a.n * ten(s - a.s) + b.n * ten(s - b.s), s);
}

Dec operator-(Dec a, Dec b) {
    b.n = -b.n;
    return a + b;
}

Dec operator*(Dec a, Dec b) {
    return Dec(a.n * b.n, a.s + b.s);
}

bool operator<(Dec a, Dec b) {
    int s = max(a.s, b.s);
    return a.n * ten(s - a.s) < b.n * ten(s - b.s);
}

int main() {
    string an, bn, s;
    int m, n, k, p;
    cin >> an >> m >> n;
    vector<vector<Dec>> a(m, vector<Dec>(n));
    int za = 0, zb = 0;
    for (auto &r : a)
        for (auto &v : r) {
            cin >> s;
            v = Dec(s);
            za += v.n == 0;
        }
    cin >> bn >> k >> p;
    vector<vector<Dec>> b(k, vector<Dec>(p)), c(m, vector<Dec>(p));
    for (auto &r : b)
        for (auto &v : r) {
            cin >> s;
            v = Dec(s);
            zb += v.n == 0;
        }
    long long mul = 0, plus = 0;
    for (int i = 0; i < m; i++)
        for (int j = 0; j < p; j++) {
            int q = 0;
            for (int z = 0; z < n; z++)
                if (a[i][z].n != 0 && b[z][j].n != 0) {
                    c[i][j] = c[i][j] + a[i][z] * b[z][j];
                    q++;
                }
            mul += q;
            plus += max(0, q - 1);
        }
    auto print = [&](vector<vector<Dec>> &v) {
        for (auto &r : v) {
            for (int i = 0; i < (int)r.size(); i++) {
                if (i)
                    cout << ' ';
                cout << r[i].str();
            }
            cout << '\n';
        }
    };
    cout << "Matrix " << an << " contains " << za << " (Zero)\n";
    print(a);
    cout << "\nMatrix " << bn << " contains " << zb << " (Zero)\n";
    print(b);
    cout << "\nMatrix C=" << an << 'X' << bn << '\n';
    print(c);
