#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
int main() {
    vector<cpp_int> a;
    cpp_int x;
    while (cin >> x)
        a.push_back(x);
    int n = a.size();
    vector<cpp_int> v = a, s(n);
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    vector<int> bit(v.size() + 1, -1), len(n), pre(n, -1);
    auto better = [&](int i, int j) {
        if (i < 0)
            return j;
        if (j < 0)
            return i;
        if (len[i] != len[j])
            return len[i] > len[j] ? i : j;
        return s[i] >= s[j] ? i : j;
    };
    int best = -1;
    for (int i = 0; i < n; i++) {
        int rank = lower_bound(v.begin(), v.end(), a[i]) - v.begin() + 1, p = -1;
        for (int k = rank - 1; k; k -= k & -k)
            p = better(p, bit[k]);
        pre[i] = p;
        len[i] = (p < 0 ? 0 : len[p]) + 1;
        s[i] = a[i] + (p < 0 ? cpp_int(0) : s[p]);
        for (int k = rank; k < (int)bit.size(); k += k & -k)
            bit[k] = better(bit[k], i);
        best = better(best, i);
    }
    vector<cpp_int> ans;
    for (int i = best; i >= 0; i = pre[i])
        ans.push_back(a[i]);
