#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
cpp_int ten(int k) {
    cpp_int x = 1;
    while (k--)
        x *= 10;
    return x;
}

struct Dec {
    cpp_int n;
    int s;
    Dec(cpp_int a = 0, int b = 0) : n(a), s(b) {
    }
    Dec(string x) {
        s = 0;
        n = 0;
        bool neg = false, point = false;
        for (char c : x) {
            if (c == '-')
                neg = true;
            else if (c == '.')
                point = true;
            else if (isdigit(c)) {
                n = n * 10 + c - '0';
                s += point;
            }
        }
        if (neg)
            n = -n;
    }
    string str() const {
        cpp_int q = n;
        bool neg = q < 0;
        if (neg)
            q = -q;
        string x = q.convert_to<string>();
        if (s) {
            if ((int)x.size() <= s)
                x = string(s + 1 - x.size(), '0') + x;
            x.insert(x.size() - s, 1, '.');
            while (x.back() == '0')
                x.pop_back();
            if (x.back() == '.')
                x.pop_back();
        }
        if (neg && q != 0)
            x = "-" + x;
        return x;
    }
};

Dec operator+(Dec a, Dec b) {
    int s = max(a.s, b.s);
    return Dec(a.n * ten(s - a.s) + b.n * ten(s - b.s), s);
}

Dec operator-(Dec a, Dec b) {
    b.n = -b.n;
    return a + b;
}

Dec operator*(Dec a, Dec b) {
    return Dec(a.n * b.n, a.s + b.s);
}

bool operator<(Dec a, Dec b) {
    int s = max(a.s, b.s);
    return a.n * ten(s - a.s) < b.n * ten(s - b.s);
}

string encode(string s) {
    string out;
    int len = 0;
    auto flush = [&]() {
        if (len) {
            out += char('0' + min(9, len));
            len = 0;
        }
    };
    for (char c : s) {
        if (isalpha((unsigned char)c))
            len++;
        else {
            flush();
            if (c == ',')
                out += '.';
        }
    }
    flush();
    return out;
}

int main() {
    string a, b;
    getline(cin, a);
    getline(cin, b);
    cout << (Dec(encode(a)) + Dec(encode(b))).str() << '\n';
}

