cpp_int countMoves = 0;
void moveDisk(int n, char a, char b) {
    cout << n << ' ' << a << ' ' << b << '\n';
    countMoves++;
}

void tower(int n, char a, char b, char c) {
    if (!n)
        return;
    tower(n - 1, a, c, b);
    moveDisk(n, a, b);
    tower(n - 1, c, b, a);
}

void target(int n, char a) {
    if (!n)
        return;
    char dest = n % 2 ? 'B' : 'C';
    if (a == dest)
        target(n - 1, a);
    else {
        char spare = 'A' + 'B' + 'C' - a - dest;
        tower(n - 1, a, spare, dest);
        moveDisk(n, a, dest);
        target(n - 1, spare);
    }
}

int main() {
    int n;
    cin >> n;
    if (n % 2)
        cout << "ERROR\n";
    else {
        target(n, 'A');
        cout << countMoves << '\n';
