            nodes.push_back({c, {x}});
            stack.back().back() = nodes.size() - 1;
        }
    }
    nodes.push_back({'s', stack[0]});
    int root = nodes.size() - 1;
    for (int test = 1; test <= 4; test++) {
        string s;
        getline(cin, s);
        int L = s.size();
        bool accepted = false;
        using Rel = vector<cpp_int>;
        Rel identity(L + 1);
        for (int i = 0; i <= L; i++)
            identity[i] = cpp_int(1) << i;
        auto compose = [&](const Rel &a, const Rel &b) {
            Rel out(L + 1);
            for (int i = 0; i <= L; i++) {
                cpp_int bits = a[i];
                while (bits != 0) {
                    unsigned j = boost::multiprecision::lsb(bits);
                    bits &= bits - 1;
                    out[i] |= b[j];
                }
            }
            return out;
        };
        for (int n = 1; n <= max(1, L) && !accepted; n++) {
            vector<Rel> dp;
            for (auto node : nodes) {
                Rel r(L + 1);
                if (node.kind == 'a' || node.kind == 'b') {
                    for (int i = 0; i < L; i++)
                        if (s[i] == node.kind)
                            r[i] = cpp_int(1) << (i + 1);
                } else if (node.kind == 's') {
                    r = identity;
                    for (int ch : node.ch)
                        r = compose(r, dp[ch]);
                } else if (node.kind == 'n') {
                    r = identity;
                    Rel b = dp[node.ch[0]];
                    int e = n;
                    while (e) {
                        if (e & 1)
                            r = compose(r, b);
                        e /= 2;
                        if (e)
                            b = compose(b, b);
                    }
                } else {
                    auto &b = dp[node.ch[0]];
                    for (int i = L; i >= 0; i--) {
                        r[i] = cpp_int(1) << i;
                        cpp_int bits = b[i];
                        while (bits != 0) {
                            int j = boost::multiprecision::lsb(bits);
                            bits &= bits - 1;
                            if (j > i)
                                r[i] |= r[j];
                        }
                    }
                }
                dp.push_back(move(r));
            }
            accepted = boost::multiprecision::bit_test(dp[root][0], L);
        }
        cout << test << ". The input string is " << (accepted ? "accepted" : "rejected")
             << '\n';
    }
}

