expr = input()
nodes = []
stack = [[]]

for c in expr:
    if c in "ab":
        nodes.append((c, []))
        stack[-1].append(len(nodes) - 1)

    elif c == "(":
        stack.append([])

    elif c == ")":
        ch = stack.pop()
        nodes.append(("s", ch))
        stack[-1].append(len(nodes) - 1)

    elif c in "n*":
        nodes.append((c, [stack[-1][-1]]))
        stack[-1][-1] = len(nodes) - 1

nodes.append(("s", stack[0]))

for test in range(1, 5):
    s = input()
    L = len(s)
    identity = [1 << i for i in range(L + 1)]

    def compose(a, b):

        out = []

        for bits in a:
            row = 0

            while bits:
                bit = bits & -bits
                bits ^= bit
                row |= b[bit.bit_length() - 1]

            out.append(row)

        return out

    accepted = False

    for n in range(1, max(1, L) + 1):
        dp = []

        for kind, ch in nodes:
            if kind in "ab":
                r = [
                    1 << (i + 1) if i < L and s[i] == kind else 0 for i in range(L + 1)
                ]

            elif kind == "s":
                r = identity

                for c in ch:
                    r = compose(r, dp[c])

            elif kind == "n":
                r = identity
                b = dp[ch[0]]
                e = n

                while e:
                    if e & 1:
                        r = compose(r, b)

                    e //= 2

                    if e:
                        b = compose(b, b)

            else:
                r = [0] * (L + 1)
                b = dp[ch[0]]

                for i in range(L, -1, -1):
                    row = 1 << i
                    bits = b[i]

                    while bits:
                        bit = bits & -bits
                        bits ^= bit
                        j = bit.bit_length() - 1

                        if j > i:
                            row |= r[j]

                    r[i] = row

            dp.append(r)

        if dp[-1][0] >> L & 1:
            accepted = True
            break

    print(f"{test}. The input string is " + ("accepted" if accepted else "rejected"))

