#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
struct Frame {
    int phase = 0;
    cpp_int a = 0, b = 0;
    char op = 0;
};

int main() {
    int t;
    cin >> t;
    string s;
    getline(cin, s);
    while (t--) {
        getline(cin, s);
        vector<Frame> st;
        bool ok = true, have = false;
        cpp_int root = 0;
        auto accept = [&](cpp_int v) {
            if (st.empty()) {
                if (have)
                    ok = false;
                have = true;
                root = v;
            } else if (st.back().phase == 0)
                st.back().a = v, st.back().phase = 1;
            else if (st.back().phase == 2)
                st.back().b = v, st.back().phase = 3;
            else
                ok = false;
        };
        size_t i = 0;
        bool began = false;
        while (i < s.size() && ok) {
            if (isspace((unsigned char)s[i])) {
                i++;
                continue;
            }
            char c = s[i];
            bool need =
                st.empty() ? !have : st.back().phase == 0 || st.back().phase == 2;
            if (need) {
                if (c == '(') {
                    st.push_back({});
                    i++;
                    began = true;
                } else if (isdigit((unsigned char)c) && !st.empty()) {
                    cpp_int v = 0;
                    while (i < s.size() && isdigit((unsigned char)s[i]))
                        v = v * 10 + s[i++] - '0';
                    accept(v);
                } else
                    ok = false;
            } else if (st.empty())
                ok = false;
            else {
                auto &f = st.back();
                if (f.phase == 1 || f.phase == 3) {
                    if (c != ',')
                        ok = false;
                    else
                        f.phase++, i++;
                } else if (f.phase == 4) {
                    if (string("+-*/").find(c) == string::npos)
                        ok = false;
                    else
                        f.op = c, f.phase = 5, i++;
                } else {
                    if (c != ')' || f.a < 0 || f.b < 0) {
                        ok = false;
                        continue;
                    }
                    cpp_int v;
                    if (f.op == '+')
                        v = f.a + f.b;
                    else if (f.op == '-')
                        v = f.a - f.b;
                    else if (f.op == '*')
                        v = f.a * f.b;
                    else {
                        if (f.b == 0 || f.a % f.b != 0) {
                            ok = false;
                            continue;
                        }
                        v = f.a / f.b;
                    }
                    st.pop_back();
                    i++;
                    accept(v);
                }
            }
        }
        if (ok && have && st.empty() && began)
            cout << root << '\n';
        else
            cout << -1 << '\n';
    }
}

