import sys

if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

for _ in range(int(sys.stdin.readline())):
    s = sys.stdin.readline().rstrip("\r\n")
    st = []
    root = None
    i = 0
    ok = True
    began = False

    def accept(v):

        global root, ok

        if not st:
            if root is not None:
                ok = False

            root = v

        elif st[-1][0] in (0, 2):
            p = st[-1][0]
            st[-1][1 if p == 0 else 2] = v
            st[-1][0] += 1

        else:
            ok = False

    while i < len(s) and ok:
        c = s[i]

        if c.isspace():
            i += 1
            continue

        need = (root is None) if not st else st[-1][0] in (0, 2)

        if need:
            if c == "(":
                st.append([0, 0, 0, ""])
                i += 1
                began = True

            elif "0" <= c <= "9" and st:
                j = i

                while i < len(s) and "0" <= s[i] <= "9":
                    i += 1

                accept(int(s[j:i]))

            else:
                ok = False

        elif not st:
            ok = False

        else:
            p, a, b, op = st[-1]

            if p in (1, 3):
                if c != ",":
                    ok = False

                else:
                    st[-1][0] += 1
                    i += 1

            elif p == 4:
                if c not in "+-*/":
                    ok = False

                else:
                    st[-1][3] = c
                    st[-1][0] = 5
                    i += 1

            else:
                if c != ")" or a < 0 or b < 0 or op == "/" and (b == 0 or a % b):
                    ok = False
                    continue

                v = (
                    a + b
                    if op == "+"
                    else a - b
                    if op == "-"
                    else a * b
                    if op == "*"
                    else a // b
                )
                st.pop()
                i += 1
                accept(v)

    print(root if ok and root is not None and not st and began else -1)

