#include <bits/stdc++.h>
using namespace std;
bool better(string a, string b) {
    return b.empty() || a.size() < b.size() || (a.size() == b.size() && a < b);
}

int main() {
    int n, k;
    cin >> n >> k;
    set<string> u;
    string s;
    while (k--) {
        cin >> s;
        u.insert(s);
    }
    vector<string> a(u.begin(), u.end());
    k = a.size();
    vector<vector<int>> ov(k, vector<int>(k));
    for (int i = 0; i < k; i++)
        for (int j = 0; j < k; j++)
            for (int l = 1; l <= n; l++)
                if (a[i].substr(n - l) == a[j].substr(0, l))
                    ov[i][j] = l;
    vector<vector<string>> dp(1 << k, vector<string>(k));
    for (int i = 0; i < k; i++)
        dp[1 << i][i] = a[i];
    for (int m = 1; m < (1 << k); m++)
        for (int i = 0; i < k; i++)
            if (!dp[m][i].empty())
                for (int j = 0; j < k; j++)
                    if (!(m >> j & 1)) {
                        string z = dp[m][i] + a[j].substr(ov[i][j]);
                        auto &cur = dp[m | 1 << j][j];
                        if (better(z, cur))
                            cur = z;
                    }
    string ans;
    for (auto z : dp.back())
        if (better(z, ans))
            ans = z;
    cout << ans << '\n';
}

