    int r = 0, c = 0;
    string path = "E";
    while (r != n - 1 || c != n - 1) {
        if (c < r && (r + 1 == n || d[r][c + 1] >= d[r + 1][c]))
            path += 'E', c++;
        else
            path += 'S', r++;
    }
    cout << path << "E\n" << d[0][0] << '\n';
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    int v = 2 * n;
    vector<array<int, 4>> p(v);
    for (auto &a : p)
        for (int &x : a)
            cin >> x;
    vector<vector<int>> d(v, vector<int>(v));
    for (int i = 0; i < v; i++)
        for (int j = 0; j < i; j++)
            for (int k = 0; k < 4; k++)
                d[i][j] += abs(p[i][k] - p[j][k]);
    auto feasible = [&](int t) {
        vector<vector<int>> g(v), r(v);
        auto edge = [&](int a, int b) {
            g[a].push_back(b);
            r[b].push_back(a);
        };
        for (int i = 0; i < v; i++)
            for (int j = 0; j < i; j++)
                if (i / 2 != j / 2 && d[i][j] > t) {
                    edge(i, j ^ 1);
                    edge(j, i ^ 1);
                }
        vector<bool> seen(v);
        vector<int> order;
        for (int s = 0; s < v; s++)
            if (!seen[s]) {
                vector<pair<int, int>> st = {{s, 0}};
                seen[s] = true;
                while (!st.empty()) {
                    auto &[u, k] = st.back();
                    if (k == (int)g[u].size()) {
                        order.push_back(u);
                        st.pop_back();
                    } else {
                        int w = g[u][k++];
                        if (!seen[w])
                            seen[w] = true, st.push_back({w, 0});
                    }
                }
            }
        vector<int> comp(v, -1);
        int c = 0;
        for (auto it = order.rbegin(); it != order.rend(); it++)
            if (comp[*it] < 0) {
                vector<int> st = {*it};
                comp[*it] = c;
                while (!st.empty()) {
                    int u = st.back();
                    st.pop_back();
                    for (int w : r[u])
                        if (comp[w] < 0)
                            comp[w] = c, st.push_back(w);
                }
                c++;
            }
        for (int i = 0; i < v; i += 2)
            if (comp[i] == comp[i + 1])
                return false;
        return true;
    };
    int lo = 0, hi = 40000;
    while (lo < hi) {
        int m = (lo + hi) / 2;
        if (feasible(m))
            hi = m;
        else
            lo = m + 1;
    }
    cout << lo << '\n';
}

