n = int(input())
v = 2 * n
p = [tuple(map(int, input().split())) for _ in range(v)]
d = [array("H", [0]) * i for i in range(v)]

for i in range(v):
    for j in range(i):
        d[i][j] = sum(abs(a - b) for a, b in zip(p[i], p[j]))


def feasible(t):

    g = [0] * v
    r = [0] * v

    for i in range(v):
        for j, c in enumerate(d[i]):
            if i // 2 != j // 2 and c > t:
                g[i] |= 1 << (j ^ 1)
                g[j] |= 1 << (i ^ 1)
                r[j ^ 1] |= 1 << i
                r[i ^ 1] |= 1 << j

    unvisited = (1 << v) - 1
    order = []

    for s in range(v):
        if not unvisited >> s & 1:
            continue

        unvisited ^= 1 << s
        stack = [s]

        while stack:
            nxt = g[stack[-1]] & unvisited

            if nxt:
                bit = nxt & -nxt
                u = bit.bit_length() - 1
                unvisited ^= bit
                stack.append(u)

            else:
                order.append(stack.pop())

    unvisited = (1 << v) - 1
    comp = [-1] * v
    cid = 0

    for s in reversed(order):
        if not unvisited >> s & 1:
            continue

        stack = [s]
        unvisited ^= 1 << s

        while stack:
            u = stack.pop()
            comp[u] = cid
            nxt = r[u] & unvisited
            unvisited ^= nxt

            while nxt:
                bit = nxt & -nxt
                nxt ^= bit
                stack.append(bit.bit_length() - 1)

        cid += 1

    return all(comp[i] != comp[i + 1] for i in range(0, v, 2))


lo = 0
hi = 40000

while lo < hi:
    mid = (lo + hi) // 2

    if feasible(mid):
        hi = mid

