#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<pair<int, int>>> g(n);
    for (int i = 1; i < n; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        --u;
        --v;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }
    int lg = 1;
    while ((1 << lg) <= n)
        lg++;
    vector<vector<int>> up(lg, vector<int>(n));
    vector<int> dep(n), tin(n), who(n), order = {0};
    vector<long long> ds(n);
    int timer = 0;
    while (!order.empty()) {
        int u = order.back();
        order.pop_back();
        tin[u] = timer;
        who[timer++] = u;
        for (auto [v, w] : g[u])
            if (v != up[0][u]) {
                up[0][v] = u;
                dep[v] = dep[u] + 1;
                ds[v] = ds[u] + w;
                order.push_back(v);
            }
    }
    for (int k = 1; k < lg; k++)
        for (int u = 0; u < n; u++)
            up[k][u] = up[k - 1][up[k - 1][u]];
    auto dist = [&](int a, int b) {
        int u = a, v = b;
        if (dep[u] < dep[v])
            swap(u, v);
        int d = dep[u] - dep[v];
        for (int k = 0; k < lg; k++)
            if (d >> k & 1)
                u = up[k][u];
        if (u != v) {
            for (int k = lg - 1; k >= 0; k--)
                if (up[k][u] != up[k][v])
                    u = up[k][u], v = up[k][v];
            u = up[0][u];
        }
        return ds[a] + ds[b] - 2 * ds[u];
    };
    set<int> s;
    long long cycle = 0;
    int d;
    cin >> d;
    while (d--) {
        int u;
        cin >> u;
        --u;
        int t = tin[u];
        auto it = s.find(t);
        if (it != s.end()) {
            s.erase(it);
            if (!s.empty()) {
                auto b = s.lower_bound(t);
                if (b == s.end())
                    b = s.begin();
                auto a = b == s.begin() ? prev(s.end()) : prev(b);
                cycle -= dist(who[*a], u) + dist(u, who[*b]) - dist(who[*a], who[*b]);
            }
        } else {
            if (!s.empty()) {
                auto b = s.lower_bound(t);
                if (b == s.end())
                    b = s.begin();
                auto a = b == s.begin() ? prev(s.end()) : prev(b);
                cycle += dist(who[*a], u) + dist(u, who[*b]) - dist(who[*a], who[*b]);
            }
            s.insert(t);
        }
        cout << cycle / 2 << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct Interval {
    ll left, right;
    int device;
};
ll solve(const vector<pair<ll, ll>> &devices) {
    vector<Interval> a;
    for (int i = 0; i < (int)devices.size(); ++i) {
        auto [x, l] = devices[i];
        if (!l)
            continue;
        a.push_back({x - l, x, i});
        a.push_back({x, x + l, i});
    }
    sort(a.begin(), a.end(), [](const Interval &x, const Interval &y) {
        return tie(x.right, x.left, x.device) < tie(y.right, y.left, y.device);
    });
    int m = a.size();
    if (!m)
        return 0;
    vector<ll> ends;
    for (auto x : a)
        ends.push_back(x.right);
    // pref[j][t] = maximum union ending at j, with predecessor index < t,
    // also allowing the one-interval chain consisting only of j.
    vector<vector<uint32_t>> pref;
    pref.reserve(m);
    ll answer = 0;
    for (int j = 0; j < m; ++j) {
        ll left = a[j].left, right = a[j].right;
        int bound = lower_bound(ends.begin(), ends.end(), left) - ends.begin();
        uint32_t best = right - left;
        vector<uint32_t> row(j + 1, best);
        for (int i = 0; i < j; ++i) {
            if (a[i].left < left && a[i].right < right && a[i].device != a[j].device) {
                uint32_t prior = pref[i][min(bound, i)];
                ll gain = right - max(left, a[i].right);
                best = max(best, (uint32_t)(prior + gain));
            }
            row[i + 1] = best;
        }
        answer = max(answer, (ll)best);
        pref.push_back(move(row));
    }
    return answer;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n) {
        vector<pair<ll, ll>> a(n);
        for (auto &[x, l] : a)
            cin >> x >> l;
        cout << solve(a) << '\n';
    }
}

