#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using I = __int128_t;
vector<ll> dp;

struct H {
    vector<int> f, b;
    int size() {
        return f.size() + b.size();
    }
    int at(int i) {
        return i < (int)f.size() ? f[f.size() - 1 - i] : b[i - f.size()];
    }
    void popL() {
        if (f.empty()) {
            int k = (b.size() + 1) / 2;
            f.assign(b.begin(), b.begin() + k);
            reverse(f.begin(), f.end());
            b.erase(b.begin(), b.begin() + k);
        }
        f.pop_back();
    }
    void popR() {
        if (b.empty()) {
            int k = (f.size() + 1) / 2;
            b.assign(f.begin(), f.begin() + k);
            reverse(b.begin(), b.end());
            f.erase(f.begin(), f.begin() + k);
        }
        b.pop_back();
    }
    bool bad(int a, int b, int c) {
        return (I)(b - a) * (dp[c] - dp[b]) <= (I)(dp[b] - dp[a]) * (c - b);
    }
    void right(int x) {
        while (size() > 1 && bad(at(size() - 2), at(size() - 1), x))
            popR();
        b.push_back(x);
    }
    void left(int x) {
        while (size() > 1 && bad(x, at(0), at(1)))
            popL();
        f.push_back(x);
    }
    ll query(ll m) {
        int l = 0, r = size() - 1;
        auto val = [&](int k) {
            int j = at(k);
            return dp[j] - j * m;
        };
        while (l < r) {
            int mid = (l + r) / 2;
            if (val(mid) <= val(mid + 1))
                r = mid;
            else
                l = mid + 1;
        }
        return val(l);
    }
};

struct Line {
    ll m, b;
    array<int, 22> up{};
    int depth = 0;
};
vector<Line> lines(1);
int top = 0;

ll value(int u, ll x) {
    return lines[u].m * x + lines[u].b;
}
bool redundant(int a, int b, ll m, ll c) {
    return (I)(lines[b].b - lines[a].b) * (lines[b].m - m) >=
           (I)(c - lines[b].b) * (lines[a].m - lines[b].m);
}

int insertLine(ll m, ll b) {
    int p = top;
    if (p)
        for (int k = 21; k >= 0; k--) {
            int v = lines[p].up[k];
            if (v && lines[v].up[0] && redundant(lines[v].up[0], v, m, b))
                p = v;
        }
    if (p && lines[p].up[0] && redundant(lines[p].up[0], p, m, b))
        p = lines[p].up[0];
    Line z;
    z.m = m;
    z.b = b;
    z.up[0] = p;
    z.depth = lines[p].depth + 1;
    for (int k = 1; k < 22; k++)
        z.up[k] = lines[z.up[k - 1]].up[k - 1];
    lines.push_back(z);
    return lines.size() - 1;
}

ll queryLine(ll x) {
    int p = top;
    for (int k = 21; k >= 0; k--) {
        int v = lines[p].up[k];
        if (v && lines[v].up[0] && value(lines[v].up[0], x) <= value(v, x))
            p = v;
    }
    if (lines[p].up[0] && value(lines[p].up[0], x) <= value(p, x))
        p = lines[p].up[0];
    return value(p, x);
}

struct Group {
    ll m;
    int count, before;
    H *h;
};

int main() {
    ios::sync_with_stdio(false);
