    ll diff = n > 1 ? a[2] - a[1] : 0;
    for (int i = 3; i <= n; i++)
        if (a[i] - a[i - 1] != diff)
            arithmetic = false;
    if (arithmetic) {
        ll q = n / c, r = n % c;
        cout << sum + llabs(diff) * (q * c * (c - 1) / 2 + r * (r - 1) / 2) << '\n';
        return 0;
    }
    bool alternating = n > 1 && a[1] != a[2];
    for (int i = 3; i <= n; i++)
        if (a[i] != a[i - 2])
            alternating = false;
    if (alternating) {
        ll hi = max(a[1], a[2]), lo = min(a[1], a[2]);
        cout << n * hi - ((a[n] == lo && n > c) ? hi - lo : 0) << '\n';
        return 0;
    }
