            auto g = st.back();
            st.pop_back();
            top = g.before;
            if (!merged) {
                merged = g.h;
                count = g.count;
            } else if (g.count >= count) {
                int z = merged->size();
                for (int k = 0; k < z; k++)
                    g.h->right(merged->at(k));
                delete merged;
                merged = g.h;
                count += g.count;
            } else {
                for (int k = g.h->size() - 1; k >= 0; k--)
                    merged->left(g.h->at(k));
                delete g.h;
                count += g.count;
            }
