        if (merged)
            push(a[i], merged, count);
        int j = i - c;
        if (j >= 0 && dp[j] < LLONG_MAX / 4) {
            ll m = a[window.front()];
            if (!st.empty() && st.back().m == m) {
                auto g = st.back();
                st.pop_back();
                top = g.before;
                g.h->right(j);
                push(m, g.h, g.count + 1);
            } else {
