class Hull:
    __slots__ = ("f", "b")

    def __init__(self):
        self.f = []
        self.b = []

    def __len__(self):
        return len(self.f) + len(self.b)

    def at(self, i):
        return self.f[-1 - i] if i < len(self.f) else self.b[i - len(self.f)]

    def pop_left(self):

        if not self.f:
            k = (len(self.b) + 1) // 2
            self.f = self.b[:k][::-1]
            self.b = self.b[k:]

        self.f.pop()

    def pop_right(self):

        if not self.b:
            k = (len(self.f) + 1) // 2
            self.b = self.f[:k][::-1]
            self.f = self.f[k:]

        self.b.pop()

    def bad(self, a, b, c):
        return (b - a) * (dp[c] - dp[b]) <= (dp[b] - dp[a]) * (c - b)

    def right(self, j):

        while len(self) > 1 and self.bad(
            self.at(len(self) - 2), self.at(len(self) - 1), j
        ):
            self.pop_right()

        self.b.append(j)

    def left(self, j):

        while len(self) > 1 and self.bad(j, self.at(0), self.at(1)):
            self.pop_left()

        self.f.append(j)

    def query(self, m):

        l = 0
        r = len(self) - 1

        while l < r:
            k = (l + r) // 2
            u = self.at(k)
            v = self.at(k + 1)

            if dp[u] - u * m <= dp[v] - v * m:
                r = k

            else:
                l = k + 1

        u = self.at(l)
        return dp[u] - u * m


