using i128 = __int128_t;

long long inv(long long a, long long m) {
    long long b = m, x = 1, y = 0;
    while (b) {
        long long q = a / b, t = a - q * b;
        a = b;
        b = t;
        t = x - q * y;
        x = y;
        y = t;
    }
    return (x % m + m) % m;
}

i128 fs(long long n, long long m, long long a, long long b) {
    i128 ans = 0;
    while (true) {
        if (a >= m) {
            ans += (i128)n * (n - 1) / 2 * (a / m);
            a %= m;
        }
        if (b >= m) {
            ans += (i128)n * (b / m);
            b %= m;
        }
        i128 y = (i128)a * n + b;
        if (y < m)
            return ans;
        n = (long long)(y / m);
        b = (long long)(y % m);
        swap(m, a);
    }
}

int main() {
    const long long P = 2023110403, Q = 2023110407, L = P * Q;
    long long A, B, N, M;
    cin >> A >> B >> N >> M;
    long long u = inv(A, P), v = inv(B, Q), z = (v - u) % Q;
    if (z < 0)
        z += Q;
    long long K = u + P * (long long)((i128)z * inv(P, Q) % Q);
    auto count = [&](long long n) {
        return fs(n, L, K, K + L - 1) - fs(n, L, K, K + L - M - 1);
    };
    long long lo = 1, hi = N;
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        if (count(mid) > 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    cout << lo << '\n';
}

