A, B, N, M = map(int, sys.stdin.read().split())
P = 2023110403
Q = 2023110407
L = P * Q
u = pow(A, -1, P)
v = pow(B, -1, Q)
K = u + P * ((v - u) * pow(P, -1, Q) % Q)


def fs(n, m, a, b):

    ans = 0

    while True:
        if a >= m:
            ans += n * (n - 1) // 2 * (a // m)
            a %= m

        if b >= m:
            ans += n * (b // m)
            b %= m

        y = a * n + b

        if y < m:
            return ans

        n, b = divmod(y, m)
        m, a = a, m


def count(n):
    return fs(n, L, K, K + L - 1) - fs(n, L, K, K + L - M - 1)


lo = 1
hi = N

while lo < hi:
    mid = (lo + hi) // 2

    if count(mid):
        hi = mid

    else:
