def nums():

    value = 0
    have = False

    while True:
        chunk = sys.stdin.buffer.read(65536)

        if not chunk:
            break

        for c in chunk:
            if 48 <= c <= 57:
                value = value * 10 + c - 48
                have = True

            elif have:
                yield value
                value = 0
                have = False

    if have:
        yield value


