#include <bits/stdc++.h>
using namespace std;
bool leap(int y) {
    return y % 400 == 0 || (y % 4 == 0 && y % 100 != 0);
}
int countCentury(int start) {
    int ans = 0;
    for (int y = start; y < start + 100; y++) {
        int w = (y + (y - 1) / 4 - (y - 1) / 100 + (y - 1) / 400) % 7;
        int days[] = {31, 28 + leap(y), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        for (int d : days) {
            ans += (w + 12) % 7 == 5;
            w = (w + d) % 7;
        }
    }
    return ans;
}

